#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Applies and verifies docs/infra/router.md and the tailnet policy (#31).
#
#   verify-router.sh          on the admin workstation: back up the router
#                             config, apply the #31 changes over SSH (each one
#                             confirmed), check the running config, write a report.
#   verify-router.sh member   on a group:team member's tailnet device: probe what
#                             the tailnet policy lets that member reach.
#
# Both modes are idempotent; changes already in place are skipped.

MODE="${1:-admin}"
ROUTER="${ROUTER:-10.10.10.1}"
REPORT="${REPORT:-router-verify-$MODE-$(date +%F).md}"
RAW=$(mktemp)
RESULTS=()
FAILED=0

# record PASS|FAIL "check" ["note"] adds one line to the result checklist.
record() {
  local mark="x"; [[ "$1" == PASS ]] || { mark=" "; FAILED=$((FAILED + 1)); }
  RESULTS+=("- [$mark] $2${3:+ — $3}")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else printf '  %s✗ %s%s\n' "$RED" "$2${3:+ ($3)}" "$RESET"; fi
}

# check "name" CMD... records PASS when CMD succeeds.
check() {
  local name="$1"; shift
  if "$@"; then record PASS "$name"; else record FAIL "$name"; fi
}

# write_report "title" writes the checklist and the raw output to $REPORT.
write_report() {
  {
    printf '## %s — %s\n\n' "$1" "$(date '+%F %H:%M')"
    printf 'Against `docs/infra/router.md` and `docs/infra/tailscale-acl.hujson`.\n\n'
    printf '%s\n' "${RESULTS[@]}"
    printf '\n<details><summary>Output</summary>\n\n```\n'
    cat "$RAW"
    printf '```\n\n</details>\n'
  } > "$REPORT"
  rm -f "$RAW"
}

# ──────────────────────────────────────────────────────────────────────────
# Member mode: run on a group:team member's device (Linux or macOS).
# ──────────────────────────────────────────────────────────────────────────

# probe HOST PORT prints "open", "closed" (refused or unreachable, which means
# the tailnet policy let the packet through) or "timeout" (dropped).
probe() {
  local host="$1" port="$2" pid i
  ( exec 3<>"/dev/tcp/$host/$port" ) 2>/dev/null &
  pid=$!
  for ((i = 0; i < 80; i++)); do
    if ! kill -0 "$pid" 2>/dev/null; then
      if wait "$pid"; then echo open; else echo closed; fi
      return
    fi
    sleep 0.1
  done
  kill "$pid" 2>/dev/null || true
  wait "$pid" 2>/dev/null || true
  echo timeout
}

# route_of HOST prints the interface the OS would send HOST's packets out of.
route_of() {
  if command -v ip >/dev/null 2>&1; then
    ip route get "$1" 2>/dev/null | head -n1
  else
    route -n get "$1" 2>/dev/null | awk '/interface:/ { print "dev " $2 }'
  fi
}

# expect allow|deny HOST PORT "what" probes HOST:PORT and records the verdict.
expect() {
  local want="$1" host="$2" port="$3" what="$4" got
  got=$(probe "$host" "$port")
  printf '%s:%s (%s) → %s via %s\n' "$host" "$port" "$what" "$got" "$(route_of "$host")" >> "$RAW"
  if [[ "$want" == allow ]]; then
    if [[ "$got" != timeout ]]; then record PASS "reaches $host:$port ($what)" "$got"
    else record FAIL "reaches $host:$port ($what)" "timed out"; fi
  else
    if [[ "$got" == timeout ]]; then record PASS "blocked from $host:$port ($what)"
    else record FAIL "blocked from $host:$port ($what)" "$got"; fi
  fi
}

if [[ "$MODE" == member ]]; then
  TOTAL_STAGES=3
  banner "Router: team member reachability (#31)"

  stage "Before you start"
  say "This proves what the tailnet policy lets a team member reach."
  step "Run it on a device logged in to Tailscale as a group:team member, NOT as the admin."
  step "Run it off the homelab VLANs and the home LAN, so the tailnet is the only path."
  step "In the cinema project, attach floating IP 10.10.30.17 to a throwaway CirrOS VM"
  note "  whose security group allows tcp 22 and 443 (CirrOS answers 22; 443 is refused)."
  say "Each probe waits up to 8 s. Open or refused means the policy let it through;"
  say "a timeout means it was dropped."
  pause "Ready? Press Enter"

  stage "Should be reachable"
  expect allow 10.10.20.12 443 "Horizon"
  expect allow 10.10.30.17 22 "cinema VM, ssh"
  expect allow 10.10.30.17 443 "cinema VM, https"
  pause

  stage "Should be blocked"
  expect deny 10.10.10.1 22 "router ssh"
  expect deny 10.10.10.2 80 "switch UI"
  expect deny 10.10.10.10 443 "iLO"
  expect deny 10.10.20.11 22 "host OS ssh"
  expect deny 10.10.30.150 22 "another project's floating IP"
  pause

  write_report "Router: team member reachability"
  finish
  if (( FAILED )); then warn "$FAILED check(s) failed; see $REPORT"
  else note "All checks passed."; fi
  note "Paste $REPORT as a comment on issue #31."
  printf '\n'
  exit 0
fi

# ──────────────────────────────────────────────────────────────────────────
# Admin mode: run on the admin workstation (home LAN, VLAN 10 or the tailnet).
# ──────────────────────────────────────────────────────────────────────────

SOCK="${TMPDIR:-/tmp}/verify-router-$$.sock"
SSH_OPTS=(-o ControlMaster=auto -o "ControlPath=$SOCK" -o ControlPersist=15m -o ConnectTimeout=5)
BACKUP="${BACKUP:-$HOME/router-backup-$(date +%F-%H%M).uci}"
trap 'ssh "${SSH_OPTS[@]}" -O exit "root@$ROUTER" >/dev/null 2>&1 || true' EXIT

# r CMD runs CMD on the router over the shared SSH connection.
r() { ssh "${SSH_OPTS[@]}" "root@$ROUTER" "$@"; }

# sections PKG OPTION VALUE prints the stable ids of PKG sections whose OPTION
# is VALUE (e.g. sections firewall name Allow-iperf3).
sections() {
  r "uci -X show $1" | sed -n "s/^$1\.\([^.]*\)\.$2='$3'\$/\1/p"
}

# staged prints the router's uncommitted uci changes.
staged() { r 'uci changes' || true; }

# delete_named PKG OPTION VALUE "what" stages deleting every matching section.
delete_named() {
  local ids id
  ids=$(sections "$1" "$2" "$3")
  if [[ -z "$ids" ]]; then note "already gone: $4"; return; fi
  for id in $ids; do r "uci delete $1.$id"; done
  printf '  %s- staged delete%s %s\n' "$YELLOW" "$RESET" "$4"
}

# SHOW holds `uci show` of network, firewall and dhcp for the checks below.
SHOW=""
load_show() { SHOW=$(r 'uci show network; uci show firewall; uci show dhcp'); }
has() { grep -qxF "$1" <<< "$SHOW"; }
# idx PKG TYPE OPTION VALUE prints e.g. "@rule[12]" for the matching section.
idx() {
  sed -n "s/^$1\.\(@$2\[[0-9]*\]\)\.$3='$4'\$/\1/p" <<< "$SHOW" | head -n1
}

rule_ok() {
  local i; i=$(idx firewall rule name "$1")
  [[ -n "$i" ]] && ! has "firewall.$i.enabled='0'"
}
rule_gone() { [[ -z "$(idx firewall rule name "$1")" ]]; }
zone_ok() {
  local i; i=$(idx firewall zone name "$1")
  [[ -n "$i" ]] && has "firewall.$i.input='$2'" && has "firewall.$i.forward='$3'" \
    && has "firewall.$i.network='$4'"
}
vlan_ok() {
  local i; i=$(idx network bridge-vlan vlan "$1")
  [[ -n "$i" ]] && has "network.$i.ports=$2"
}
iface_ok() { has "network.$1.device='$2'" && has "network.$1.ipaddr='$3'"; }
dhcp_ok() { has "dhcp.$1.start='$2'" && has "dhcp.$1.limit='$3'"; }
# forwardings prints "src>dest" for every forwarding out of a homelab zone.
forwardings() {
  awk -F"'" '
    /^firewall\.@forwarding\[[0-9]+\]\.src=/  { split($0, a, "."); s[a[2]] = $2 }
    /^firewall\.@forwarding\[[0-9]+\]\.dest=/ { split($0, a, "."); d[a[2]] = $2 }
    END { for (k in s) if (s[k] ~ /^(lan|mgmt_test|services|workload|tailscale)$/) print s[k] ">" d[k] }' <<< "$SHOW" | sort | tr '\n' ' '
}

# export_clean prints the homelab part of the running config: only sections
# whose interfaces, zones and VLANs are the homelab's, and no MACs, DUIDs or
# host names.
export_clean() {
  r 'uci export network; uci export firewall; uci export dhcp' | awk -v q="'" '
    BEGIN {
      split("loopback lan wan wan6 MGMT_TEST SERVICES WORKLOAD tailscale", a, " ")
      for (i in a) ifaces[a[i]] = 1
      split("* lan wan mgmt_test services workload tailscale", a, " ")
      for (i in a) zones[a[i]] = 1
      split("1 10 20 30", a, " ")
      for (i in a) vlans[a[i]] = 1
    }
    function val(line,   p) { p = index(line, q); line = substr(line, p + 1); return substr(line, 1, index(line, q) - 1) }
    function flush() { if (buf != "" && keep) printf "%s", buf; buf = ""; keep = 1 }
    /^package / { flush(); print; next }
    /^config / {
      flush()
      if ($1 == "config" && $2 == "host") keep = 0
      if (($2 == "interface" || $2 == "dhcp") && $3 != "" && !(val($0) in ifaces)) keep = 0
    }
    /dhcp_default_duid|ula_prefix|option mac|list mac|macaddr/ { next }
    /option (src|dest) / && !(val($0) in zones) { keep = 0 }
    /option interface / && !(val($0) in ifaces) { keep = 0 }
    /list network / && !(val($0) in ifaces) { keep = 0 }
    /option vlan / && !(val($0) in vlans) { keep = 0 }
    /option name / && inzone && !(val($0) in zones) { keep = 0 }
    /^config / { inzone = ($2 == "zone") }
    { buf = buf $0 "\n" }
    END { flush() }'
}

TOTAL_STAGES=9
banner "Router: apply and verify (#31)"

stage "Before you start"
say "This applies the #31 changes to the OpenWrt Router and checks it against"
say "docs/infra/router.md. Run it on the admin workstation."
say "Changes are staged with uci and committed together in stage 6, after you review them."
note "Router: root@$ROUTER (override with ROUTER=...). Type the root password once."
r true
record PASS "SSH to the router"
pending=$(staged)
if [[ -n "$pending" ]]; then
  warn "The router already has uncommitted uci changes:"
  printf '%s\n' "$pending" | sed 's/^/    /'
  confirm "Keep them and commit them along with this run?" \
    || { r 'for p in network firewall dhcp; do uci revert $p; done'; note "reverted"; }
fi
pause

stage "Back up the running config"
say "Saving network, firewall and dhcp to $BACKUP (stays on this machine; never commit it)."
( umask 077; r 'uci export network; uci export firewall; uci export dhcp' > "$BACKUP" )
record PASS "Backup saved before changes"
note "Restore: scp it to the router, then uci import <pkg> < file for each package."
pause

stage "Firewall: rescue port → switch UI"
say "Add Allow-Rescue-Switch: lan (rescue port lan3) → 10.10.10.2 tcp 80."
if [[ -n "$(sections firewall name Allow-Rescue-Switch)" ]]; then
  note "already present"
elif confirm "Stage this rule?"; then
  r 'uci batch' <<'EOF'
add firewall rule
set firewall.@rule[-1].name='Allow-Rescue-Switch'
set firewall.@rule[-1].src='lan'
set firewall.@rule[-1].dest='mgmt_test'
set firewall.@rule[-1].dest_ip='10.10.10.2'
set firewall.@rule[-1].proto='tcp'
set firewall.@rule[-1].dest_port='80'
set firewall.@rule[-1].target='ACCEPT'
EOF
  printf '  %s+ staged%s Allow-Rescue-Switch\n' "$GREEN" "$RESET"
fi
pause

stage "Firewall: tailnet → router"
say "Add Allow-Tailscale-Router: tailscale → router, tcp 22, 80, 443."
say "The tailnet policy keeps team members off it."
if [[ -n "$(sections firewall name Allow-Tailscale-Router)" ]]; then
  note "already present"
elif confirm "Stage this rule?"; then
  r 'uci batch' <<'EOF'
add firewall rule
set firewall.@rule[-1].name='Allow-Tailscale-Router'
set firewall.@rule[-1].src='tailscale'
set firewall.@rule[-1].proto='tcp'
set firewall.@rule[-1].dest_port='22 80 443'
set firewall.@rule[-1].target='ACCEPT'
EOF
  printf '  %s+ staged%s Allow-Tailscale-Router\n' "$GREEN" "$RESET"
fi
pause

stage "Firewall: disabled leftovers"
say "Delete the three disabled rules left over from earlier tries:"
note "  Allow-Tailscale-Horizon, Allow-Tailscale-Workload-HTTPS, Allow-iperf3"
if confirm "Stage these deletes?"; then
  for name in Allow-Tailscale-Horizon Allow-Tailscale-Workload-HTTPS Allow-iperf3; do
    delete_named firewall name "$name" "rule $name"
  done
fi
pause

stage "Review and commit"
pending=$(staged)
if [[ -z "$pending" ]]; then
  note "Nothing staged; the router already matches."
else
  say "Staged changes:"
  printf '%s\n' "$pending" | sed 's/^/    /'
  printf 'staged changes\n%s\n\n' "$pending" >> "$RAW"
  if confirm "Commit and reload network, firewall and dnsmasq?"; then
    r 'uci commit network && uci commit firewall && uci commit dhcp &&
       service network reload && service firewall reload && service dnsmasq reload'
    record PASS "Changes committed and services reloaded"
  else
    r 'for p in network firewall dhcp; do uci revert $p; done'
    record FAIL "Changes committed" "reverted at review"
  fi
fi
pause

stage "Tailnet policy"
say "Apply docs/infra/tailscale-acl.hujson in the Tailscale admin console."
open_url "https://login.tailscale.com/admin/acls/file"
step "Back up the current policy text somewhere private first."
step "Replace the whole policy with docs/infra/tailscale-acl.hujson."
step "Replace admin@example.com and teammate@example.com with the real logins."
step "Save. The console runs the tests block and refuses the policy if any fail."
step "Machines → the router → Edit route settings: all three routes approved."
if confirm "Saved without test failures, and all three routes approved?"; then
  record PASS "Tailnet policy saved; its tests pass"
else
  ask why "What went wrong?"; record FAIL "Tailnet policy saved; its tests pass" "$why"
fi
pause

stage "Running config vs router.md"
load_show
printf '$ uci export network firewall dhcp (MACs, DUID, host names removed)\n%s\n\n' "$(export_clean)" >> "$RAW"

check "VLAN 1 untagged on lan1 and lan3" vlan_ok 1 "'lan1:u*' 'lan3:u*'"
for v in 10 20 30; do check "VLAN $v tagged on lan1" vlan_ok "$v" "'lan1:t'"; done
check "lan is 192.168.99.1/24 on br-lan.1" iface_ok lan br-lan.1 192.168.99.1/24
check "MGMT_TEST is 10.10.10.1/24 on br-lan.10" iface_ok MGMT_TEST br-lan.10 10.10.10.1/24
check "SERVICES is 10.10.20.1/24 on br-lan.20" iface_ok SERVICES br-lan.20 10.10.20.1/24
check "WORKLOAD is 10.10.30.1/24 on br-lan.30" iface_ok WORKLOAD br-lan.30 10.10.30.1/24

check "DHCP lan .100–.249" dhcp_ok lan 100 150
check "DHCP off on MGMT_TEST" has "dhcp.MGMT_TEST.ignore='1'"
check "DHCP SERVICES .100–.199" dhcp_ok SERVICES 100 100
check "DHCP WORKLOAD .50–.89" dhcp_ok WORKLOAD 50 40

check "Zone lan: input ACCEPT, forward ACCEPT" zone_ok lan ACCEPT ACCEPT lan
check "Zone mgmt_test: input ACCEPT, forward REJECT" zone_ok mgmt_test ACCEPT REJECT MGMT_TEST
check "Zone services: input REJECT, forward REJECT" zone_ok services REJECT REJECT SERVICES
check "Zone workload: input REJECT, forward REJECT" zone_ok workload REJECT REJECT WORKLOAD
check "Zone tailscale: input REJECT, forward REJECT" zone_ok tailscale REJECT REJECT tailscale
fw=$(forwardings)
if [[ "$fw" == "mgmt_test>wan services>wan workload>wan " ]]; then
  record PASS "Forwardings: mgmt_test, services, workload → wan only"
else
  record FAIL "Forwardings: mgmt_test, services, workload → wan only" "found: $fw"
fi

for name in Allow-Rescue-Switch Allow-DHCP-Services Allow-DNS-Services Block-Services-HomeLAN \
            Allow-DHCP-Workload Allow-DNS-Workload Block-Workload-HomeLAN Block-MGMT-HomeLAN \
            Allow-Admin-OpenWrt Allow-Admin-Homelab Allow-Tailscale-Router Allow-Tailscale-MGMT \
            Allow-Tailscale-Services Allow-Tailscale-Workload Block-All-IPv6-Forward Block-All-IPv6-Input; do
  check "Rule $name present and enabled" rule_ok "$name"
done
for name in Allow-Tailscale-Horizon Allow-Tailscale-Workload-HTTPS Allow-iperf3; do
  check "Rule $name removed" rule_gone "$name"
done
pause

stage "Tailscale on the router"
routes=$(r "tailscale debug prefs" | awk '/"AdvertiseRoutes"/ { on = 1; next } on && /\]/ { exit } on' | tr -d ' ",')
printf '$ tailscale debug prefs: AdvertiseRoutes\n%s\n\n' "$routes" >> "$RAW"
printf '%s\n' "$routes" | sed 's/^/    /'
for net in 10.10.10.0/24 10.10.20.0/24 10.10.30.0/24; do
  check "Advertises $net" grep -qx "$net" <<< "$routes"
done
check "tailscaled is running" r 'tailscale status >/dev/null'
say ""
say "Rescue port: plug a laptop into lan3; it should get a 192.168.99.x lease"
say "and open http://10.10.10.2 (the switch UI)."
if confirm "Did you test the rescue port?"; then
  if confirm "Did the laptop reach the switch UI?"; then record PASS "Rescue port reaches the switch UI"
  else record FAIL "Rescue port reaches the switch UI"; fi
else
  note "Skipped; recorded as not tested."
  RESULTS+=("- [ ] Rescue port reaches the switch UI — not tested")
fi
pause

write_report "Router verification"
finish
note "Backup of the previous config: $BACKUP"
if (( FAILED )); then warn "$FAILED check(s) failed; see $REPORT"
else note "All checks passed."; fi
note "Paste $REPORT as a comment on issue #31."
printf '\n'
